-- Consulta: VendaGeraMovimento
-- Tipo: Acréscimo (64)
-- Descrição: 

INSERT INTO [F Movimento Contas] ( LinkVenda, IndiceReajuste, Plano3, Plano2, Plano1, ClassificacaoVenda, Efetuado, EmpVinculada, CodigoParceiro, CodAtribuiParceiro, CodAtribuiEmpresa, CodHistorico, DataMovto, ValorDebito, ValorCredito, Complemento, ContaFinanceira, Confirmado, Integracao, DataPagto, DataVencto, MovPagtoLote, SelPagtoLote, Observacao, NumDoc, CodImovel, AgrupadorVenda, SofreReajuste, CodAnteriorParceiro, CodAnteriorEmpresa, ValorOriginalImovel, CodigoCondPagto )
SELECT TempVendaImovel.LinkVenda, TempVendaImovel.IndiceReajuste, TempVendaImovel.Plano3, Plano2.Plano2, Plano1.Plano1, TempVendaImovel.ClassificacaoVenda, TempVendaImovel.Efetuado, TempVendaImovel.EmpVinculada, TempVendaImovel.CodigoParceiro, TempVendaImovel.CodAtribuiParceiro, TempVendaImovel.CodAtribuiEmpresa, TempVendaImovel.CodHistorico, TempVendaImovel.DataMovto, TempVendaImovel.ValorDebito, TempVendaImovel.ValorCredito, TempVendaImovel.Complemento, TempVendaImovel.ContaFinanceira, TempVendaImovel.Confirmado, TempVendaImovel.Integracao, TempVendaImovel.DataPagto, TempVendaImovel.DataVencto, TempVendaImovel.MovPagtoLote, TempVendaImovel.SelPagtoLote, TempVendaImovel.Observacao, TempVendaImovel.NumDoc, TempVendaImovel.CodImovel, TempVendaImovel.AgrupadorVenda, TempVendaImovel.SofreReajuste, TempVendaImovel.CodAnteriorParceiro, TempVendaImovel.CodAnteriorEmpresa, TempVendaImovel.ValorOriginalImovel, TempVendaImovel.CodigoCondPagto
FROM (Plano1 INNER JOIN Plano2 ON Plano1.Plano1=Plano2.Plano1) INNER JOIN (TempVendaImovel INNER JOIN Plano3 ON TempVendaImovel.Plano3=Plano3.Plano3) ON Plano2.Plano2=Plano3.Plano2;
